package com.nimbusbill.customer.controller;
import com.nimbusbill.customer.dto.*; import com.nimbusbill.customer.entity.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import tools.jackson.databind.ObjectMapper; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class PricingControllerTest{
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;
 @Test void approvalLifecycleAndFixedPreview() throws Exception{String suffix=UUID.randomUUID().toString().substring(0,8).toUpperCase();ProductRequest product=new ProductRequest("PX_"+suffix,"Pricing Test Product",null,PricingUnit.FIXED,null,null,true,ProductStatus.ACTIVE,LocalDate.now(),null);String productBody=mvc.perform(post("/api/v1/products").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(product))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();UUID productId=UUID.fromString(json.readTree(productBody).get("id").asText());PricingRuleRequest rule=new PricingRuleRequest(productId,PricingUnit.FIXED,new BigDecimal("5.00"),null,null,null,new BigDecimal("18"),1,List.of());PricingPlanRequest request=new PricingPlanRequest("PLAN_"+suffix,"Test Plan",null,"INR",LocalDate.now(),null,List.of(rule));String body=mvc.perform(post("/api/v1/pricing-plans").header("X-Actor","maker").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(request))).andExpect(status().isCreated()).andExpect(jsonPath("$.versions[0].status").value("DRAFT")).andReturn().getResponse().getContentAsString();var tree=json.readTree(body);String planId=tree.get("id").asText();String versionId=tree.get("versions").get(0).get("id").asText();mvc.perform(post("/api/v1/pricing-plans/{p}/versions/{v}/submit",planId,versionId)).andExpect(status().isOk()).andExpect(jsonPath("$.versions[0].status").value("PENDING_APPROVAL"));mvc.perform(post("/api/v1/pricing-plans/{p}/versions/{v}/approve",planId,versionId).header("X-Actor","maker")).andExpect(status().isConflict());mvc.perform(post("/api/v1/pricing-plans/{p}/versions/{v}/approve",planId,versionId).header("X-Actor","checker")).andExpect(status().isOk()).andExpect(jsonPath("$.versions[0].status").value("APPROVED"));mvc.perform(post("/api/v1/pricing-plans/{p}/versions/{v}/activate",planId,versionId)).andExpect(status().isOk()).andExpect(jsonPath("$.versions[0].status").value("ACTIVE"));PricingPreviewRequest preview=new PricingPreviewRequest(UUID.fromString(planId),product.productCode(),new BigDecimal("1000"),LocalDate.now());mvc.perform(post("/api/v1/pricing/preview").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(preview))).andExpect(status().isOk()).andExpect(jsonPath("$.baseFee").value(5.0)).andExpect(jsonPath("$.taxAmount").value(0.9)).andExpect(jsonPath("$.totalCharge").value(5.9));ClonePricingVersionRequest clone=new ClonePricingVersionRequest(LocalDate.now().plusDays(30),null);mvc.perform(post("/api/v1/pricing-plans/{p}/versions/{v}/clone",planId,versionId).header("X-Actor","maker-2").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(clone))).andExpect(status().isOk()).andExpect(jsonPath("$.versions[0].versionNumber").value(2)).andExpect(jsonPath("$.versions[0].status").value("DRAFT")).andExpect(jsonPath("$.versions[0].rules[0].fixedFee").value(5.0));}
}
